import json

try:
    with open('store.json', 'r') as f:
        store = json.load(f)
except FileNotFoundError:
    store = {}
except json.JSONDecodeError as e:
    print(f'Error decoding JSON in store.json: {e}')
    exit(2)

def set(key, value):
    try:
        store[key] = value
        with open('store.json', 'w') as f:
            json.dump(store, f, sort_keys=True, indent=2)
    except (ValueError, OSError) as e:
        print(f'Error writing to store.json: {e}')
        exit(1)

def get(key):
    return store.get(key, None)

def delete(key):
    if key in store:
        del store[key]
        with open('store.json', 'w') as f:
            json.dump(store, f, sort_keys=True, indent=2)

def recover(damaged_file, out_file):
    try:
        with open(damaged_file, 'r') as f:
            damaged_store = f.read()
    except FileNotFoundError:
        print(f'Error opening {damaged_file}: File not found')
        exit(2)

    recovered_entries = 0
    for entry in damaged_store.split(',
')[:-1]:
        try:
            key, value = entry.split(': ', 1)
            store[key] = json.loads(value)
            recovered_entries += 1
        except (ValueError, json.JSONDecodeError) as e:
            print(f'Error parsing entry {entry}: {e}')

    with open(out_file, 'w') as f:
        json.dump(store, f, sort_keys=True, indent=2)

    print(f'Recovered {recovered_entries} entries')
    exit(2)
